from pathlib import Path
import base64

def dec(value: str) -> str:
    return base64.b64decode(value.encode('ascii')).decode('utf-8')

PAYLOADS = {
    'PACKAGE': 'ewogICJuYW1lIjogInNod2FwZSIsCiAgInByaXZhdGUiOiB0cnVlLAogICJ0eXBlIjogIm1vZHVsZSIsCiAgInNjcmlwdHMiOiB7CiAgICAidGVzdCI6ICJub2RlIC0tdGVzdCB0ZXN0cy8qLnRlc3QubWpzIgogIH0KfQo=',
    'SMOKE_TEST': '',
    'CI': '',
    'TECH_ADDENDUM': '',
    'REDIRECT': '',
}

ROOT = Path('.')

(ROOT / 'shvape.html').write_text(dec(PAYLOADS['REDIRECT']), encoding='utf-8')
(ROOT / 'package.json').write_text(dec(PAYLOADS['PACKAGE']), encoding='utf-8')
(ROOT / 'tests').mkdir(exist_ok=True)
(ROOT / 'tests' / 'smoke.test.mjs').write_text(dec(PAYLOADS['SMOKE_TEST']), encoding='utf-8')
(ROOT / '.github' / 'workflows').mkdir(parents=True, exist_ok=True)
(ROOT / '.github' / 'workflows' / 'ci.yml').write_text(dec(PAYLOADS['CI']), encoding='utf-8')

tech_path = ROOT / 'TECH_REVIEW.md'
tech = tech_path.read_text(encoding='utf-8')
if 'Repair pass — 2026-11-08' not in tech:
    tech_path.write_text(tech.rstrip() + dec(PAYLOADS['TECH_ADDENDUM']) + '\n', encoding='utf-8')
print('SHVAPE files repair applied')
